package org.apache.parquet.filter2;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.*;

public class IncrementallyUpdatedFilterPredicateGeneratorRunTests {

  @Test
  void generatesExpectedClassStructure(@TempDir Path tempDir) throws IOException {
    File outJava = tempDir.resolve("IncrementallyUpdatedFilterPredicateBuilder.java").toFile();
    IncrementallyUpdatedFilterPredicateGenerator generator = new IncrementallyUpdatedFilterPredicateGenerator(outJava);
    generator.run();

    String content = Files.readString(outJava.toPath());

    // Basic structure checks
    assertTrue(content.startsWith("package org.apache.parquet.filter2.recordlevel;"), "Generated file should declare the recordlevel package at top");
    assertTrue(content.contains("public class IncrementallyUpdatedFilterPredicateBuilder extends IncrementallyUpdatedFilterPredicateBuilderBase"),
        "Generated builder class declaration should extend base");
    assertTrue(content.contains("public IncrementallyUpdatedFilterPredicateBuilder(List<PrimitiveColumnIO> leaves)"),
        "Constructor with leaves argument should be generated");

    // Ensure presence of various predicate handling methods
    assertTrue(content.contains("visit(Eq<T> pred)"), "Eq visit should be generated");
    assertTrue(content.contains("visit(NotEq<T> pred)"), "NotEq visit should be generated");
    assertTrue(content.contains("visit(In<T> pred)"), "In visit should be generated");
    assertTrue(content.contains("visit(NotIn<T> pred)"), "NotIn visit should be generated");
    assertTrue(content.contains("visit(Contains<T> pred)"), "Contains visit should be generated");
    assertTrue(content.contains("visit(Lt<T> pred)"), "Lt visit should be generated");
    assertTrue(content.contains("visit(LtEq<T> pred)"), "LtEq visit should be generated");
    assertTrue(content.contains("visit(Gt<T> pred)"), "Gt visit should be generated");
    assertTrue(content.contains("visit(GtEq<T> pred)"), "GtEq visit should be generated");
  }
}
